import base64,subprocess,json,hashlib,time
from pathlib import Path
R=Path('/storage/qa587')
FILES={'observer.py': '', 'fake-rclone': ''}
for n,v in FILES.items():(R/n).write_bytes(base64.b64decode(v))
(R/'fake-rclone').chmod(0o755)
subprocess.run(['cp','/usr/bin/rclone',str(R/'rclone-original')],check=True)
subprocess.run(['mount','--bind',str(R/'fake-rclone'),'/usr/bin/rclone'],check=True)
subprocess.run(['mount','--make-private','/usr/bin/rclone'],check=True)
subprocess.run(['systemctl','set-environment','CLOUD_SIGNIN_DEBUG=1'],check=True)
subprocess.run(['systemctl','start','essway'],check=True)
(R/'phase').write_text('idle-proxy-stopped')
subprocess.run(['systemd-run','--unit=qa587-observer','--property=RuntimeMaxSec=1500','/usr/bin/python3','-I','-B',str(R/'observer.py')],check=True)
print('Synthetic browser fixture staged; observer and frontend started.')
